def banner():
    os.system("clear")
    banner_text = decode_str(ENCODED_BANNER)
    title_text = decode_str(ENCODED_TITLE)
    try:
        print(render(banner_text, colors=["cyan", "white"]))
    except:
        print(banner_text)
    print(COLORS['cyan'] + title_text + COLORS['reset'])

logging.basicConfig(level=logging.WARNING, format='%(asctime)s - %(message)s')

success_count = 0
unsuccess_count = 0
counter_lock = asyncio.Lock()

def print_stats():
    sys.stdout.write(f"\r{COLORS['green']}successful: {success_count}{COLORS['reset']} {COLORS['red']}unsuccessful: {unsuccess_count}{COLORS['reset']}")
    sys.stdout.flush()

async def send_loop(context, dm_url, target_name):
    global success_count, unsuccess_count
    page = await context.new_page()
    await page.route("**/*.{png,jpg,jpeg,gif,webp,svg,mp4,webm,ogg}", lambda route: route.abort())
    await page.route("**/ads/**", lambda route: route.abort())
    
    page.set_default_timeout(600000)
    page.set_default_navigation_timeout(600000)
    
    msg_count = 0
    while True:
        try:
            # Add navigation with reload-like behavior
            await page.goto(dm_url, wait_until='domcontentloaded', timeout=600000)
            msg_input = page.locator('div[aria-label="Message"][role="textbox"]')
            await msg_input.wait_for(timeout=600000)
            
            while True:
                try:
                    # Random reload every 50-100 messages to prevent memory/DOM bloat
                    if msg_count > 0 and msg_count % random.randint(50, 100) == 0:
                        print(f"\n{COLORS['yellow']}Reloading page to maintain stability...{COLORS['reset']}")
                        await asyncio.sleep(5) # Small gap before reload
                        break # Break inner loop to trigger page.goto reload
                    base_msg = random.choice(MESSAGES)
                    msg = base_msg.replace("{target}", target_name)
                    await msg_input.fill(msg, timeout=600000)
                    await page.keyboard.press("Enter")
                    
                    async with counter_lock:
                        success_count += 1
                        msg_count += 1
                        print_stats()
                    
                    if msg_count >= 500:
                        msg_count = 0
                        break
                        
                    await asyncio.sleep(random.uniform(2, 5))
                except Exception:
                    async with counter_lock:
                        unsuccess_count += 1
                        print_stats()
                    await asyncio.sleep(5)
                    try:
                        await msg_input.wait_for(timeout=600000)
                    except:
                        break
        except Exception:
            await asyncio.sleep(10)

async def main():
    banner()
    
    session_id = input("Session ID: ").strip()
    
    print(f"\n{COLORS['cyan']}How would you like to provide Group Chat URLs?{COLORS['reset']}")
    print("1. Bulk paste (space/comma/newline separated)")
    print("2. Read from file (links.txt)")
    choice = input("Choice (1/2): ").strip()
    
    dm_urls = []
    if choice == "2":
        try:
            with open("links.txt", "r") as f:
                dm_urls = [line.strip() for line in f if line.strip()]
            print(f"Loaded {len(dm_urls)} URLs from links.txt")
        except FileNotFoundError:
            print("links.txt not found! Falling back to bulk paste.")
            choice = "1"
            
    if choice == "1":
        print("Paste your GC URLs below (press Enter twice to finish):")
        lines = []
        while True:
            line = sys.stdin.readline().strip()
            if not line:
                break
            # Split by common separators
            parts = line.replace(",", " ").split()
            lines.extend(parts)
        dm_urls = [url for url in lines if url.startswith("http")]
    
    if not dm_urls:
        print("No valid URLs provided! Exiting.")
        sys.exit(1)
        
    target_name = input("Target Name (will replace {target} in messages): ").strip() or "USER"

    try:
        task_count = int(input(f"Number of concurrent tasks (default {min(len(dm_urls) * 2, 80)}, max 80): ").strip() or str(min(len(dm_urls) * 2, 80)))
        if task_count > 80:
            task_count = 80
    except:
        task_count = 30

    async with async_playwright() as p:
        browser = await p.chromium.launch(
            headless=True, 
            args=[
                '--no-sandbox', 
                '--disable-gpu', 
                '--disable-dev-shm-usage',
                '--disable-extensions',
                '--disable-setuid-sandbox',
                '--no-first-run',
                '--no-zygote',
                '--js-flags="--max-old-space-size=512"'
            ]
        )
        context = await browser.new_context()
        await context.add_cookies([{
            "name": "sessionid",
            "value": session_id,
            "domain": ".instagram.com",
            "path": "/",
            "httpOnly": True,
            "secure": True,
            "sameSite": "None"
        }])

        print(f"\nStarting {task_count} concurrent tasks across {len(dm_urls)} groups...")
        
        # Distribute URLs among tasks
        tasks = []
        for i in range(task_count):
            url = dm_urls[i % len(dm_urls)]
            tasks.append(asyncio.create_task(send_loop(context, url, target_name)))

        try:
            await asyncio.gather(*tasks)
        except KeyboardInterrupt:
            pass
        finally:
            print_stats()
            print()
            await browser.close()

if __name__ == "__main__":
    asyncio.run(main())
